head.script:
scwin.onpageload = function() {};
scwin.onpageunload = function() {};
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. main샘플 실행 후 'useNameLayer false'버튼을 클릭한다.
    //1. After running the main sample, click the 'useNameLayer false' button.
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "countInit = WebSquare.wUnit.getJq('#windowContainer1_name').children().length");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_3').click()");
    WebSquare.wUnit.addCommand("pause", "100");
    //Verify step 1. windowContainer하단에 nameLayer Tab이 정상적으로 보이지 않는다.(기능추가됨)
    //1. The nameLayer Tab is not normally displayed at the bottom of windowContainer (added function)
    WebSquare.wUnit.addCommand("assert", "countInit == WebSquare.wUnit.getJq('#windowContainer1_name').children().length", "true");
    WebSquare.wUnit.addCommand("pause", "100");
    //Test step 2. 'useNameLayer true'버튼을 클릭한다.
    //2. Click the 'useNameLayer true' button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_4').click()");
    WebSquare.wUnit.addCommand("pause", "100");
    //Verify step 2. windowContainer하단에 nameLayer Tab('local01')이 정상적으로 보여진다.
    //2. At the bottom of windowContainer, nameLayer Tab ('local01') is displayed normally.
    WebSquare.wUnit.addCommand("assert", "countInit != WebSquare.wUnit.getJq('#windowContainer1_name').children().length", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('windowContainer1_name').childNodes[0].innerText == 'local01'", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function 
    //Created by: Quan.Nguyen
    //Created date: 14-Jun-2018
    var countInit;
    //end
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}

